import React, { useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import './Education.css';

const educationData = [
  {
    id: 1,
    period: "2024 - 2028",
    status: "Currently Pursuing",
    statusClass: "current",
    degree: "B.Tech in Artificial Intelligence and Data Science",
    institution: "Vishwakarma Institute of Technology, Pune - 411037",
    icon: "fas fa-graduation-cap",
    highlights: [
      { icon: "fas fa-brain", text: "AI & Data Science" },
      { icon: "fas fa-chart-line", text: "Data Analytics" },
      { icon: "fas fa-code", text: "Software Development" }
    ],
    description: "Pursuing a comprehensive education in AI and data science, data analytics, and software development. Gaining hands-on experience with cutting-edge technologies and real-world applications.",
    tags: ["🤖 AI", "📊 Data Science", "💻 Full Stack"],
    socials: [
      { icon: "fab fa-linkedin", url: "https://www.linkedin.com/school/vishwakarma-institute-of-technology-pune/" },
      { icon: "fab fa-instagram", url: "https://www.instagram.com/official_vitpune?igsh=Y3NuMXo1OGwwYXNm" }
    ],
    academyLink: null
  },
  {
    id: 2,
    period: "2022 - 2024",
    status: "Completed",
    statusClass: "completed",
    degree: "Higher Secondary Education (PCM)",
    institution: "HRSPM - 410505",
    icon: "fas fa-school",
    highlights: [
      { icon: "fas fa-atom", text: "Physics" },
      { icon: "fas fa-flask", text: "Chemistry" },
      { icon: "fas fa-calculator", text: "Mathematics" }
    ],
    description: "I completed my higher secondary education at Vision Academy after beginning at HRSPM College. With a strong academic focus, I consistently achieved excellent results and successfully qualified for JEE Advanced, building a solid foundation in engineering and technology.",
    tags: ["⚛️ Physics", "🧪 Chemistry", "📐 Mathematics"],
    socials: [],
    academyLink: { name: "Vision Academy", url: "https://www.instagram.com/visionacademy_?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==" }
  }
];

const Education = () => {
  const containerRef = useRef(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start center", "end center"]
  });

  return (
    <section id="education" className="education-premium">
      {/* Background animated gradients */}
      <div className="edu-bg-orb orb-1"></div>
      <div className="edu-bg-orb orb-2"></div>

      <div className="container">
        <motion.div
          className="section-header-crazy"
          initial={{ opacity: 0, y: -50 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.8, type: "spring" }}
        >
          <span className="section-badge pulse-badge">🎓 Academic Journey</span>
          <h2 className="section-title-crazy">
            Education
          </h2>
          <p className="section-subtitle">Building knowledge through quality education</p>
        </motion.div>

        <div className="timeline-container" ref={containerRef}>
          {/* Center glowing line */}
          <div className="timeline-center-line">
            <motion.div
              className="timeline-progress"
              style={{ scaleY: scrollYProgress }}
            />
          </div>

          <div className="timeline-items">
            {educationData.map((edu, index) => (
              <TimelineItem key={edu.id} data={edu} index={index} />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

const TimelineItem = ({ data, index }) => {
  const isEven = index % 2 === 1; // index 0 = left, index 1 = right

  const cardVariants = {
    hidden: { opacity: 0, x: isEven ? 80 : -80, rotateY: isEven ? -15 : 15 },
    visible: {
      opacity: 1,
      x: 0,
      rotateY: 0,
      transition: { duration: 0.8, type: "spring", bounce: 0.3 }
    }
  };

  return (
    <div className={`edu-timeline-item ${isEven ? 'right-side' : 'left-side'}`}>
      <motion.div
        className="timeline-dot"
        initial={{ scale: 0 }}
        whileInView={{ scale: 1 }}
        viewport={{ once: true, amount: 0.8 }}
        transition={{ duration: 0.4, delay: 0.2 }}
      >
        <div className="dot-inner"></div>
        <div className="dot-ripple"></div>
      </motion.div>

      <motion.div
        className="edu-card-container"
        variants={cardVariants}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, amount: 0.2 }}
        whileHover={{ scale: 1.03, y: -8, transition: { duration: 0.2 } }}
      >
        <div className="edu-card-premium">
          <div className={`card-border-glow ${data.statusClass}`}></div>

          <div className="edu-card-content">
            <div className="edu-card-header">
              <div className="edu-year">
                <span className="year-text">{data.period}</span>
              </div>
              <div className={`edu-status-badge ${data.statusClass}`}>
                <span className="status-indicator"></span>
                {data.status}
              </div>
            </div>

            <div className="edu-icon-wrapper">
              <i className={data.icon}></i>
            </div>

            <h3 className="edu-degree">{data.degree}</h3>
            <h4 className="edu-institution">
              <i className="fas fa-university"></i> {data.institution}
            </h4>

            <div className="edu-highlights-tags">
              {data.highlights.map((hl, i) => (
                <span key={i} className="hl-tag">
                  <i className={hl.icon}></i> {hl.text}
                </span>
              ))}
            </div>

            <p className="edu-desc">{data.description}</p>

            <div className="edu-footer">
              <div className="edu-skills">
                {data.tags.map((tag, i) => (
                  <span key={i} className="skill-badge">{tag}</span>
                ))}
              </div>

              <div className="edu-actions">
                {data.socials && data.socials.map((social, i) => (
                  <motion.a
                    key={i}
                    href={social.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    whileHover={{ scale: 1.2, rotate: 360, boxShadow: "0 0 20px rgba(99, 102, 241, 0.6)" }}
                    className="social-btn"
                  >
                    <i className={social.icon}></i>
                  </motion.a>
                ))}
                {data.academyLink && (
                  <motion.a
                    href={data.academyLink.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    whileHover={{ scale: 1.05, boxShadow: "0 0 20px rgba(139, 92, 246, 0.5)" }}
                    className="academy-btn"
                  >
                    {data.academyLink.name}
                  </motion.a>
                )}
              </div>
            </div>
          </div>
        </div>
      </motion.div>
    </div>
  );
};

export default Education;
